const PipesConnectedAccountSchema = z
  .object({
    object: z
      .literal('connected_account')
      .openapi({ description: 'The connected account object.', example: 'connected_account' }),
    id: z
      .string()
      .openapi({
        description: 'The unique ID of the connected account.',
        example: 'data_installation_01EHZNVPK3SFK441A1RGBFSHRT',
      }),
    connection_role: z
      .enum(['compatibility', 'standard'])
      .exactOptional()
      .openapi({
        description:
          'Whether this is the compatibility connection visible to undeclared clients or a standard connection for plural-aware clients. Historical events may omit this field.',
        example: 'compatibility',
      }),
    account_identifier: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'A best-effort identifier for the provider account this connection points at. It is not the connection identifier or a selector. Historical events may omit this field.',
        example: 'workspace_123',
      }),
    account_display_name: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'A mutable, non-unique display name for the provider account connection. Historical events may omit this field.',
        example: 'Acme production',
      }),
    data_integration_id: z
      .string()
      .openapi({
        description: 'The unique ID of the data integration.',
        example: 'data_integration_01EHZNVPK3SFK441A1RGBFSHRT',
      }),
    provider_slug: z
      .string()
      .openapi({ description: 'The provider slug for this connected account.', example: 'github' }),
    user_id: z
      .string()
      .nullable()
      .openapi({
        description: 'The ID of the User the connected account belongs to.',
        example: 'user_01EHZNVPK3SFK441A1RGBFSHRT',
      }),
    organization_id: z
      .string()
      .nullable()
      .openapi({
        description: 'The ID of the Organization the connected account belongs to.',
        example: 'org_01EHWNCE74X7JSDV0X3SZ3KJNY',
      }),
    scopes: z
      .array(z.string())
      .openapi({
        description: 'The OAuth scopes granted for this connected account.',
        example: ['repo', 'user:email'],
      }),
    auth_method: z
      .enum(['oauth', 'api_key', 'client_credentials'])
      .exactOptional()
      .openapi({
        description: 'How the connection authenticates. Historical events may omit this field.',
        example: 'oauth',
      }),
    api_key_last_4: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The last four characters of the API key, or null for other authentication methods. Historical events may omit this field.',
        example: null,
      }),
    state: z
      .enum(['connected', 'needs_reauthorization'])
      .openapi({ description: 'The state of the connected account.', example: 'connected' }),
    established_by_user_id: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The ID of the User whose authorization established the connected account, or null when it is developer-managed, its establisher is unknown, or the establishing member left the organization. Historical events may omit this field.',
        example: 'user_01EHZNVPK3SFK441A1RGBFSHRT',
      }),
    state_reason: z
      .xor([z.literal('establishing_member_membership_ended'), z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          'Why WorkOS put the connected account in its current state, or null when there is no WorkOS-recorded reason. `establishing_member_membership_ended` means the member who established an organization-owned connection is no longer an active member. Additional values may be added. Historical events may omit this field.',
        example: null,
      }),
    created_at: z.iso
      .datetime({ offset: true })
      .openapi({ description: 'An ISO 8601 timestamp.', example: '2026-01-15T12:00:00.000Z' }),
    updated_at: z.iso
      .datetime({ offset: true })
      .openapi({ description: 'An ISO 8601 timestamp.', example: '2026-01-15T12:00:00.000Z' }),
  })
  .openapi({
    required: [
      'object',
      'id',
      'data_integration_id',
      'provider_slug',
      'user_id',
      'organization_id',
      'scopes',
      'state',
      'created_at',
      'updated_at',
    ],
  })
  .openapi('PipesConnectedAccount')

const UserlandUserSchema = z
  .object({
    object: z.literal('user').openapi({ description: 'Distinguishes the user object.' }),
    id: z
      .string()
      .openapi({
        description: 'The unique ID of the user.',
        example: 'user_01E4ZCR3C56J083X43JQXF3JK5',
      }),
    first_name: z
      .string()
      .nullable()
      .openapi({ description: 'The first name of the user.', example: 'Marcelina' }),
    last_name: z
      .string()
      .nullable()
      .openapi({ description: 'The last name of the user.', example: 'Davis' }),
    name: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: "The user's full name.", example: 'Marcelina Davis' }),
    profile_picture_url: z
      .string()
      .nullable()
      .openapi({
        description: 'A URL reference to an image representing the user.',
        example: 'https://workoscdn.com/images/v1/123abc',
      }),
    email: z
      .string()
      .openapi({
        description: 'The email address of the user.',
        example: 'marcelina.davis@example.com',
      }),
    email_verified: z
      .boolean()
      .openapi({ description: "Whether the user's email has been verified.", example: true }),
    external_id: z
      .string()
      .nullable()
      .openapi({
        description: 'The external ID of the user.',
        example: 'f1ffa2b2-c20b-4d39-be5c-212726e11222',
      }),
    metadata: z
      .record(z.string(), z.string().max(600))
      .refine((val) => Object.keys(val).length <= 50)
      .exactOptional()
      .openapi({
        description: 'Object containing metadata key/value pairs associated with the user.',
        example: { timezone: 'America/New_York' },
      }),
    last_sign_in_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({
        description: 'The timestamp when the user last signed in.',
        example: '2025-06-25T19:07:33.155Z',
      }),
    locale: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: "The user's preferred locale.", example: 'en-US' }),
    created_at: z.iso
      .datetime({ offset: true })
      .openapi({ description: 'An ISO 8601 timestamp.', example: '2026-01-15T12:00:00.000Z' }),
    updated_at: z.iso
      .datetime({ offset: true })
      .openapi({ description: 'An ISO 8601 timestamp.', example: '2026-01-15T12:00:00.000Z' }),
  })
  .openapi({
    required: [
      'object',
      'id',
      'first_name',
      'last_name',
      'profile_picture_url',
      'email',
      'email_verified',
      'external_id',
      'last_sign_in_at',
      'created_at',
      'updated_at',
    ],
    description: 'The user object.',
  })
  .openapi('UserlandUser')

