const UserObjectSchema = z
  .object({
    id: z
      .string()
      .openapi({
        description:
          "Your application's user identifier, which will be stored as an [`external_id`](/authkit/metadata/external-identifiers). Used for upserting and deduplication.",
        example: 'user_12345',
      }),
    email: z
      .string()
      .openapi({
        description: "The user's email address.",
        example: 'marcelina.davis@example.com',
      }),
    first_name: z
      .string()
      .exactOptional()
      .openapi({ description: "The user's first name.", example: 'Marcelina' }),
    last_name: z
      .string()
      .exactOptional()
      .openapi({ description: "The user's last name.", example: 'Davis' }),
    name: z
      .string()
      .exactOptional()
      .openapi({ description: "The user's full name.", example: 'Marcelina Davis' }),
    metadata: z
      .record(z.string(), z.string().max(600))
      .refine((val) => Object.keys(val).length <= 50)
      .exactOptional()
      .openapi({
        description: 'A set of key-value pairs to attach to the user.',
        example: { department: 'Engineering', role: 'Developer' },
      }),
  })
  .openapi({ required: ['id', 'email'] })
  .openapi('UserObject')

