const InviteItContactDtoSchema = z
  .object({
    intents: z
      .array(
        z.enum([
          'sso',
          'directory_sync',
          'log_streams',
          'domain_verification',
          'bring_your_own_key',
        ]),
      )
      .min(1)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({
        description: 'The Admin Portal features that the IT contact can configure.',
        example: ['sso', 'directory_sync'],
      }),
  })
  .openapi({ required: ['intents'] })
  .openapi('InviteItContactDto')

