const TokenQueryDtoSchema = z
  .object({
    client_id: z
      .string()
      .openapi({
        description: 'The client ID of the WorkOS environment.',
        example: 'client_01HZBC6N1EB1ZY7KG32X',
      }),
    client_secret: z
      .string()
      .openapi({
        description: 'The client secret of the WorkOS environment.',
        example: 'sk_example_123456789',
      }),
    code: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The authorization code received from the authorization callback. Required when `grant_type` is `authorization_code`.',
        example: 'authorization_code_value',
      }),
    grant_type: z
      .enum(['authorization_code', 'urn:ietf:params:oauth:grant-type:token-exchange'])
      .openapi({
        description: 'The grant type for the token request.',
        example: 'authorization_code',
      }),
    code_verifier: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The PKCE code verifier matching the `code_challenge` sent with the authorization request. Required when the authorization request included a `code_challenge`. Must be sent in the request body.',
        example: 'code_verifier_value',
      }),
    subject_token: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The OIDC ID token to exchange. Required when `grant_type` is `urn:ietf:params:oauth:grant-type:token-exchange`. Must be sent in the request body.',
        example: 'eyJhbGciOiJSUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjMifQ.example',
      }),
    subject_token_type: z
      .literal('urn:ietf:params:oauth:token-type:id_token')
      .exactOptional()
      .openapi({
        description:
          'The type of the subject token. Required when `grant_type` is `urn:ietf:params:oauth:grant-type:token-exchange`. Must be sent in the request body.',
        example: 'urn:ietf:params:oauth:token-type:id_token',
      }),
    organization_id: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The ID of the organization whose connection the subject token is validated against. Required when `grant_type` is `urn:ietf:params:oauth:grant-type:token-exchange`. Must be sent in the request body.',
        example: 'org_01EHQMYV6MBK39QC5PZXHY59C3',
      }),
  })
  .openapi({ required: ['client_id', 'client_secret', 'grant_type'] })
  .openapi('TokenQueryDto')

