export const postAgentsBlueprintsRoute = createRoute({
  method: 'post',
  path: '/agents/blueprints',
  tags: ['agents.blueprints'],
  summary: 'Create an agent blueprint',
  description:
    'Creates an agent blueprint: the template describing what an agent may do (its permission ceiling), who may invoke it, and the lifetimes of its sessions.',
  operationId: 'AgentBlueprintsController_create',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z
                .string()
                .min(1)
                .max(255)
                .openapi({
                  description: 'Human-readable name of the agent blueprint.',
                  example: 'Prospecting Agent',
                }),
              description: z
                .string()
                .min(1)
                .max(1000)
                .exactOptional()
                .openapi({
                  description: 'Human-readable description of the agent blueprint.',
                  example: 'Finds and qualifies sales prospects.',
                }),
              permissions: z
                .array(z.string().min(1))
                .max(1000)
                .default([])
                .exactOptional()
                .openapi({
                  description:
                    'Permission slugs forming the ceiling on what sessions minted from this blueprint may do. Each slug must exist in the environment.',
                  example: ['crm:read', 'email:send'],
                }),
              invocable_by: z
                .object({
                  role_slugs: z
                    .array(z.string().min(1))
                    .max(100)
                    .default([])
                    .exactOptional()
                    .openapi({
                      description:
                        'Role slugs whose members may mint user-delegated sessions from this blueprint. An empty list allows any member.',
                      example: ['manager'],
                    }),
                  organization_ids: z
                    .array(z.string().min(1))
                    .max(1000)
                    .default([])
                    .exactOptional()
                    .openapi({
                      description:
                        'Organizations in which sessions may be minted from this blueprint, enforced on user-delegated, autonomous, and agent-delegated mints. An empty list allows any organization in the environment.',
                      example: ['org_01EHWNCE74X7JSDV0X3SZ3KJNY'],
                    }),
                })
                .default({})
                .exactOptional()
                .openapi({
                  description: 'Who may mint sessions from this blueprint.',
                  required: [],
                }),
              invocable_as: z
                .object({
                  instance_types: z
                    .array(z.enum(['delegated', 'autonomous']))
                    .min(1)
                    .max(2)
                    .default(['delegated', 'autonomous'])
                    .exactOptional()
                    .openapi({
                      description:
                        'Instance types that may be minted from this blueprint: `delegated` (a user-delegated session, minted with a user access token) and/or `autonomous` (a session acting as the agent itself, minted with an agent registration credential). Agent-delegated chaining and refreshes are checked against the type of the presenting instance. Defaults to both.',
                      example: ['delegated', 'autonomous'],
                    }),
                })
                .default({})
                .exactOptional()
                .openapi({
                  description: 'How sessions may be minted from this blueprint.',
                  required: [],
                }),
              session_settings: z
                .object({
                  max_age_seconds: z
                    .int()
                    .gt(0)
                    .max(31536000)
                    .openapi({
                      description:
                        'Maximum lifetime of a session in seconds; refreshes never extend a session past this. At most 31,536,000 (365 days).',
                      example: 3600,
                    }),
                  access_token_ttl_seconds: z
                    .int()
                    .gt(0)
                    .max(3600)
                    .openapi({
                      description:
                        'Lifetime of each minted access token in seconds. At most 3,600 (1 hour).',
                      example: 300,
                    }),
                  refresh_token_ttl_seconds: z
                    .int()
                    .gt(0)
                    .max(5184000)
                    .openapi({
                      description:
                        'Lifetime of each rotated refresh token in seconds. At most 5,184,000 (60 days).',
                      example: 3600,
                    }),
                })
                .default({
                  max_age_seconds: 3600,
                  access_token_ttl_seconds: 300,
                  refresh_token_ttl_seconds: 3600,
                })
                .exactOptional()
                .openapi({
                  required: [
                    'max_age_seconds',
                    'access_token_ttl_seconds',
                    'refresh_token_ttl_seconds',
                  ],
                  description:
                    'Token and session lifetimes for sessions minted from this blueprint.',
                }),
            })
            .openapi({
              required: ['name'],
              description: 'Configuration for the new agent blueprint.',
            }),
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Created',
      content: { 'application/json': { schema: AgentBlueprintSchema } },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: ErrorBodyWithCodeSchema } },
    },
    409: { description: '', content: { 'application/json': { schema: ErrorBodyWithCodeSchema } } },
    422: {
      description: 'Unprocessable Entity',
      content: { 'application/json': { schema: ErrorBodyWithCodeSchema } },
    },
  },
})

