export const postAgentsBlueprintsAgentBlueprintIdTokensRoute = createRoute({
  method: 'post',
  path: '/agents/blueprints/{agent_blueprint_id}/tokens',
  tags: ['agents.blueprints.tokens'],
  summary: 'Mint an agent token',
  description:
    'Mint an agent access token (and backing session) from an agent blueprint. The session can be user-delegated (exchanging a user access token), autonomous (the agent acting as itself in an organization), agent-delegated (the agent exchanging its own access token for a new session on the same instance), or a refresh of a previously issued refresh token.',
  operationId: 'AgentBlueprintsTokenController_mintToken',
  request: {
    params: z.object({
      agent_blueprint_id: z
        .string()
        .openapi({
          param: {
            name: 'agent_blueprint_id',
            required: true,
            in: 'path',
            description: 'The unique ID of the agent blueprint.',
            schema: { type: 'string', example: 'agent_blueprint_01EHWNCE74X7JSDV0X3SZ3KJNY' },
          },
          example: 'agent_blueprint_01EHWNCE74X7JSDV0X3SZ3KJNY',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .discriminatedUnion('type', [
              z
                .object({
                  type: z
                    .literal('user_delegated')
                    .openapi({
                      description:
                        'How the session is minted: `user_delegated`, `autonomous`, `agent_delegated`, or `refresh`.',
                    }),
                  user_access_token: z
                    .string()
                    .min(1)
                    .openapi({
                      description:
                        'The access token of the user delegating to the agent. The token identifies the user and organization; effective permissions are resolved server-side.',
                      example: 'eyJhbGciOiJSUzI1NiIsImtpZCI6...',
                    }),
                  intent: z
                    .string()
                    .min(1)
                    .max(255)
                    .exactOptional()
                    .openapi({
                      description:
                        'Optional caller-supplied context, echoed as an object with a `text` field in the `intent` claim of the minted access token.',
                      example: 'renew-contract-123',
                    }),
                })
                .openapi({ required: ['type', 'user_access_token'] }),
              z
                .object({
                  type: z
                    .literal('autonomous')
                    .openapi({
                      description:
                        'How the session is minted: `user_delegated`, `autonomous`, `agent_delegated`, or `refresh`.',
                    }),
                  organization_id: z
                    .string()
                    .min(1)
                    .openapi({
                      description:
                        'The organization the agent acts within when operating as itself.',
                      example: 'org_01EHWNCE74X7JSDV0X3SZ3KJNY',
                    }),
                  intent: z
                    .string()
                    .min(1)
                    .max(255)
                    .exactOptional()
                    .openapi({
                      description:
                        'Optional caller-supplied context, echoed as an object with a `text` field in the `intent` claim of the minted access token.',
                      example: 'renew-contract-123',
                    }),
                })
                .openapi({ required: ['type', 'organization_id'] }),
              z
                .object({
                  type: z
                    .literal('agent_delegated')
                    .openapi({
                      description:
                        'How the session is minted: `user_delegated`, `autonomous`, `agent_delegated`, or `refresh`.',
                    }),
                  agent_access_token: z
                    .string()
                    .min(1)
                    .openapi({
                      description:
                        "The agent's own access token to exchange for a new session on the same instance. The token must have been minted from this blueprint; permissions are re-derived from current authority.",
                      example: 'eyJhbGciOiJSUzI1NiIsImtpZCI6...',
                    }),
                  intent: z
                    .string()
                    .min(1)
                    .max(255)
                    .exactOptional()
                    .openapi({
                      description:
                        'Optional caller-supplied context, echoed as an object with a `text` field in the `intent` claim of the minted access token.',
                      example: 'renew-contract-123',
                    }),
                })
                .openapi({ required: ['type', 'agent_access_token'] }),
              z
                .object({
                  type: z
                    .literal('refresh')
                    .openapi({
                      description:
                        'How the session is minted: `user_delegated`, `autonomous`, `agent_delegated`, or `refresh`.',
                    }),
                  refresh_token: z
                    .string()
                    .min(1)
                    .openapi({
                      description:
                        'The refresh token issued with a previous agent access token. Refresh tokens are single-use: each refresh rotates it.',
                      example: 'njGkA8Wyht0GBEGGA0Zh1Q3wZzL2...',
                    }),
                  intent: z
                    .string()
                    .min(1)
                    .max(255)
                    .exactOptional()
                    .openapi({
                      description:
                        'Optional caller-supplied context, echoed as an object with a `text` field in the `intent` claim of the minted access token.',
                      example: 'renew-contract-123',
                    }),
                })
                .openapi({ required: ['type', 'refresh_token'] }),
            ])
            .openapi({
              discriminator: { propertyName: 'type' },
              description:
                'How to mint the agent session, discriminated by `type`. `intent` is optional on every variant.',
            }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: { description: 'OK', content: { 'application/json': { schema: AgentTokenSchema } } },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: ErrorBodyWithCodeSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: ErrorBodyWithCodeSchema } },
    },
    404: { description: 'Not Found', content: { 'application/json': { schema: ErrorBodySchema } } },
  },
})

