export const postDataIntegrationsFinishRoute = createRoute({
  method: 'post',
  path: '/data-integrations/finish',
  tags: ['pipes'],
  summary: 'Finish connection',
  description:
    'Saves a connection that was started with `code_challenge`. After the user authorizes, WorkOS redirects them to `return_to` with a `connect_code` and `state`. Call this endpoint from your server with that `connect_code` and the `code_verifier` behind the challenge to save the connected account.',
  operationId: 'DataIntegrationsController_finishConnection',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              connect_code: z
                .string()
                .regex(/^[A-Za-z0-9_-]{43}$/)
                .openapi({
                  description:
                    'The `connect_code` WorkOS added to `return_to` when the user finished authorizing. It can be used once and expires 90 seconds after the redirect.',
                  example: 'Q3n0bWh2b0tqZ1VtV2ZsYkJ3cE9aV0J6T1hGb1lYaGo',
                }),
              code_verifier: z
                .string()
                .regex(/^[A-Za-z0-9._~-]{43,128}$/)
                .openapi({
                  description:
                    'The code verifier `code_challenge` was derived from: 43 to 128 characters from `A-Z`, `a-z`, `0-9`, `-`, `.`, `_` and `~`. A wrong verifier uses up the `connect_code`, and the user has to connect again.',
                  example: 'dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk',
                }),
              state: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The `state` WorkOS added to `return_to` alongside `connect_code`. Optional; it is only used to correlate the request in logs.',
                  example: 'q2czJKmVAraSBg8xFpT7M9uR',
                }),
            })
            .openapi({ required: ['connect_code', 'code_verifier'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: { 'application/json': { schema: DataIntegrationFinishConnectionResponseSchema } },
    },
    400: {
      description:
        'The connection could not be completed, and the user must connect again. `invalid_connect_code` when the `connect_code` is unknown, expired, already used, or from another environment, or the `code_verifier` does not match the `code_challenge`. Other codes report why saving the connection failed, such as `target_deleted` when the connected account being reauthorized was deleted in the meantime. A malformed request body returns validation messages instead.',
      content: {
        'application/json': {
          schema: z.union([
            ConnectionFinishErrorBodySchema,
            ErrorBodyWithMessageOrMessageListSchema,
          ]),
        },
      },
    },
    401: { description: 'Unauthorized' },
    403: { description: 'Forbidden', content: { 'application/json': { schema: ErrorBodySchema } } },
  },
})

