export const postDataIntegrationsSlugCredentialsRoute = createRoute({
  method: 'post',
  path: '/data-integrations/{slug}/credentials',
  tags: ['pipes'],
  summary: 'Vend credentials for a connected account',
  description:
    "Returns credentials for a user's connected account. Branches on the installation's `auth_method`: OAuth installations return an access token (refreshed if needed); API-key installations return the stored secret. Every active credential includes `config`: provider-declared, non-secret values from the installation snapshot, with current provider defaults for unset fields. Editing integration or organization configuration does not change the snapshot; reconnect or explicitly rebind the connection to adopt those edits. Defaults remain live, so a changed default can appear in `config` before a cached token is refreshed or re-minted. Credentials that never refresh require a reconnect or rebind when a default changes their routing.",
  operationId: 'DataIntegrationsController_vendCredentials',
  request: {
    params: z.object({
      slug: z
        .string()
        .openapi({
          param: {
            name: 'slug',
            required: true,
            in: 'path',
            description: 'The identifier of the integration.',
            schema: { example: 'github', type: 'string' },
          },
          example: 'github',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              user_id: z
                .string()
                .openapi({
                  description:
                    'A [User](/reference/authkit/user) identifier. When `connection_owner` is `organization`, this is the user the credentials are vended on behalf of; they must be an active member of the organization.',
                  example: 'user_01EHZNVPK3SFK441A1RGBFSHRT',
                }),
              organization_id: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'An [Organization](/reference/organization) identifier. Optional parameter to scope the connection to a specific organization. Required when `connection_owner` is `organization`.',
                  example: 'org_01EHZNVPK3SFK441A1RGBFSHRT',
                }),
              connected_account_id: z
                .string()
                .min(1)
                .exactOptional()
                .openapi({
                  description:
                    'A [connected account](/reference/pipes/connected-account) identifier. Use this to select a specific connection when the user has several for this provider.',
                  example: 'data_installation_01EHZNVPK3SFK441A1RGBFSHRT',
                }),
              connection_owner: z
                .enum(['user', 'organization'])
                .exactOptional()
                .openapi({
                  description:
                    "Which connection to vend from. `user` (the default) vends the user's own connection and requires `user_id`. `organization` vends the organization's shared connection and requires `organization_id`.",
                  example: 'user',
                }),
              supports_multiple_connections: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Set to `true` to use the plural connection contract. If no `connected_account_id` is supplied and several connections match, the request returns `account_selection_required`. When omitted or `false`, only the compatibility connection is considered.',
                  example: true,
                }),
            })
            .openapi({ required: ['user_id'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: DataIntegrationCredentialsResponseSchema,
          example: {
            active: true,
            credential: {
              object: 'credential',
              auth_method: 'oauth',
              value: 'gho_16C7e42F292c6912E7710c838347Ae178B4a',
              expires_at: '2025-12-31T23:59:59.000Z',
              scopes: ['repo', 'user:email'],
              missing_scopes: [],
              metadata: {},
              config: {},
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: ErrorBodySchema } },
    },
    401: { description: 'Unauthorized' },
    403: {
      description:
        'The user is not an active member of the organization named for an organization connection or an organization-scoped personal connection.',
      content: { 'application/json': { schema: ErrorBodySchema } },
    },
    404: {
      description: 'The data integration or selected connected account was not found.',
      content: { 'application/json': { schema: ErrorBodySchema } },
    },
    409: {
      description:
        'Several connected accounts match this user or organization for the provider; one must be named.',
      content: { 'application/json': { schema: AccountSelectionRequiredErrorSchema } },
    },
    422: {
      description:
        'The installation uses an auth method that is not yet supported by this endpoint.',
      content: { 'application/json': { schema: ErrorBodySchema } },
    },
  },
})

