export const postDirectoriesIdSyncRoute = createRoute({
  method: 'post',
  path: '/directories/{id}/sync',
  tags: ['directories'],
  summary: 'Sync a Directory',
  description:
    'Request an asynchronous sync from the directory provider. Currently supports Google Workspace directories in linked or validating state. Manual requests share a five-minute per-directory cooldown across the API, Dashboard, Admin Portal, and MCP. Acceptance means the request was queued, not that the sync has started or completed. A running sync prevents another request from being queued.',
  operationId: 'DirectoriesController_syncDirectory',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            name: 'id',
            required: true,
            in: 'path',
            description: 'Unique identifier for the Directory.',
            schema: { example: 'directory_01ECAZ4NV9QMV47GW873HDCX74', type: 'string' },
          },
          example: 'directory_01ECAZ4NV9QMV47GW873HDCX74',
        }),
    }),
  },
  responses: {
    202: {
      description: '',
      content: { 'application/json': { schema: DirectorySyncResponseSchema } },
    },
    403: { description: 'Forbidden', content: { 'application/json': { schema: ErrorBodySchema } } },
    404: { description: 'Not Found', content: { 'application/json': { schema: ErrorBodySchema } } },
    409: {
      description: 'A sync is already in progress. No additional sync was queued.',
      content: { 'application/json': { schema: ErrorBodyWithCodeSchema } },
    },
    422: {
      description: 'The directory provider or state does not support manual sync.',
      content: { 'application/json': { schema: ErrorBodyWithCodeSchema } },
    },
    429: {
      description: 'The directory is within the manual-sync cooldown window.',
      content: { 'application/json': { schema: DirectorySyncRateLimitErrorSchema } },
      headers: z.object({
        'Retry-After': z
          .int()
          .min(1)
          .exactOptional()
          .openapi({
            description: 'Seconds to wait before requesting another manual sync.',
            param: { required: false },
          }),
      }),
    },
    503: {
      description: 'Directory syncing is temporarily paused. No sync was queued.',
      content: { 'application/json': { schema: ErrorBodyWithCodeSchema } },
    },
  },
})

