export const getSsoAuthorizeRoute = createRoute({
  method: 'get',
  path: '/sso/authorize',
  tags: ['sso'],
  summary: 'Initiate SSO',
  description: 'Initiates the single sign-on flow.',
  operationId: 'SsoController_authorize',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const open: string[] = ['provider_query_params']
        const taken: string[] = [
          'provider_scopes',
          'client_id',
          'domain',
          'provider',
          'redirect_uri',
          'response_type',
          'state',
          'connection',
          'organization',
          'domain_hint',
          'login_hint',
          'nonce',
          'prompt',
        ]
        for (const [key, item] of Object.entries(val)) {
          if (!taken.includes(key)) {
            for (const owner of open) {
              group(owner)[key] = item
            }
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          provider_scopes: z
            .preprocess(
              (val) =>
                val === undefined
                  ? val
                  : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                      typeof item === 'string' ? item.split(',') : [item],
                    ),
              z.array(z.string()),
            )
            .exactOptional()
            .openapi({
              param: {
                name: 'provider_scopes',
                required: false,
                in: 'query',
                description:
                  'Additional scopes to request from the identity provider. Applicable when using OAuth or OpenID Connect connections.',
                style: 'form',
                explode: false,
                schema: {
                  type: 'array',
                  items: { type: 'string' },
                  example: ['openid', 'profile', 'email'],
                },
              },
              example: ['openid', 'profile', 'email'],
            }),
          provider_query_params: z
            .record(z.string(), z.string())
            .exactOptional()
            .openapi({
              param: {
                name: 'provider_query_params',
                required: false,
                in: 'query',
                description:
                  'Key/value pairs of query parameters to pass to the OAuth provider. Only applicable when using OAuth connections.',
                schema: {
                  additionalProperties: { type: 'string' },
                  example: { hd: 'example.com', access_type: 'offline' },
                  type: 'object',
                },
              },
              example: { hd: 'example.com', access_type: 'offline' },
            }),
          client_id: z
            .string()
            .openapi({
              param: {
                name: 'client_id',
                required: true,
                in: 'query',
                schema: { type: 'string', example: 'client_01HZBC6N1EB1ZY7KG32X' },
                description: 'The unique identifier of the WorkOS environment client.',
              },
              example: 'client_01HZBC6N1EB1ZY7KG32X',
            }),
          domain: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'domain',
                required: false,
                in: 'query',
                deprecated: true,
                schema: { type: 'string', example: 'example.com' },
                description:
                  'Deprecated. Use `connection` or `organization` instead. Used to initiate SSO for a connection by domain. The domain must be associated with a connection in your WorkOS environment.',
              },
              example: 'example.com',
            }),
          provider: z
            .enum([
              'AppleOAuth',
              'BitbucketOAuth',
              'GitHubOAuth',
              'GitLabOAuth',
              'GoogleOAuth',
              'IntuitOAuth',
              'LinkedInOAuth',
              'MicrosoftOAuth',
              'SalesforceOAuth',
              'SlackOAuth',
              'VercelMarketplaceOAuth',
              'VercelOAuth',
              'XeroOAuth',
            ])
            .exactOptional()
            .openapi({
              param: {
                name: 'provider',
                required: false,
                in: 'query',
                schema: {
                  type: 'string',
                  enum: [
                    'AppleOAuth',
                    'BitbucketOAuth',
                    'GitHubOAuth',
                    'GitLabOAuth',
                    'GoogleOAuth',
                    'IntuitOAuth',
                    'LinkedInOAuth',
                    'MicrosoftOAuth',
                    'SalesforceOAuth',
                    'SlackOAuth',
                    'VercelMarketplaceOAuth',
                    'VercelOAuth',
                    'XeroOAuth',
                  ],
                  example: 'GoogleOAuth',
                },
                description: 'Used to initiate OAuth authentication with various providers.',
              },
              example: 'GoogleOAuth',
            }),
          redirect_uri: z
            .url()
            .openapi({
              param: {
                name: 'redirect_uri',
                required: true,
                in: 'query',
                schema: { type: 'string', format: 'uri', example: 'https://example.com/callback' },
                description:
                  'Where to redirect the user after they complete the authentication process. You must use one of the redirect URIs configured via the [Redirects](https://dashboard.workos.com/redirects) page on the dashboard.',
              },
              example: 'https://example.com/callback',
            }),
          response_type: z
            .literal('code')
            .openapi({
              param: {
                name: 'response_type',
                required: true,
                in: 'query',
                schema: { type: 'string', example: 'code', const: 'code' },
                description:
                  'The only valid option for the response type parameter is `"code"`.\n\nThe `"code"` parameter value initiates an [authorization code grant type](https://tools.ietf.org/html/rfc6749#section-4.1). This grant type allows you to exchange an authorization code for an access token during the redirect that takes place after a user has authenticated with an identity provider.',
              },
              example: 'code',
            }),
          state: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'state',
                required: false,
                in: 'query',
                schema: { type: 'string', example: 'dj1kUXc0dzlXZ1hjUQ==' },
                description:
                  'An optional parameter that can be used to encode arbitrary information to help restore application state between redirects. If included, the redirect URI received from WorkOS will contain the exact `state` that was passed.',
              },
              example: 'dj1kUXc0dzlXZ1hjUQ==',
            }),
          connection: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'connection',
                required: false,
                in: 'query',
                schema: { type: 'string', example: 'conn_01E4ZCR3C56J083X43JQXF3JK5' },
                description:
                  'Used to initiate SSO for a connection. The value should be a WorkOS connection ID.\n\nYou can persist the WorkOS connection ID with application user or team identifiers. WorkOS will use the connection indicated by the connection parameter to direct the user to the corresponding IdP for authentication.',
              },
              example: 'conn_01E4ZCR3C56J083X43JQXF3JK5',
            }),
          organization: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'organization',
                required: false,
                in: 'query',
                schema: { type: 'string', example: 'org_01EHQMYV6MBK39QC5PZXHY59C3' },
                description:
                  'Used to initiate SSO for an organization. The value should be a WorkOS organization ID.\n\nYou can persist the WorkOS organization ID with application user or team identifiers. WorkOS will use the organization ID to determine the appropriate connection and the IdP to direct the user to for authentication.',
              },
              example: 'org_01EHQMYV6MBK39QC5PZXHY59C3',
            }),
          domain_hint: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'domain_hint',
                required: false,
                in: 'query',
                schema: { type: 'string', example: 'example.com' },
                description:
                  'Can be used to pre-fill the domain field when initiating authentication with Microsoft OAuth or with a Google SAML connection type.',
              },
              example: 'example.com',
            }),
          login_hint: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'login_hint',
                required: false,
                in: 'query',
                schema: { type: 'string', example: 'user@example.com' },
                description:
                  'Can be used to pre-fill the username/email address field of the IdP sign-in page for the user, if you know their username ahead of time. Currently supported for OAuth, OpenID Connect, Okta, Entra ID, and custom SAML connections.',
              },
              example: 'user@example.com',
            }),
          nonce: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'nonce',
                required: false,
                in: 'query',
                schema: { type: 'string', example: 'abc123def456' },
                description:
                  'A random string generated by the client that is used to mitigate replay attacks.',
              },
              example: 'abc123def456',
            }),
          prompt: z
            .literal('login')
            .exactOptional()
            .openapi({
              param: {
                name: 'prompt',
                required: false,
                in: 'query',
                schema: { type: 'string', example: 'login', const: 'login' },
                description:
                  'If set to `login`, forces re-authentication at the identity provider. For supported SAML providers this sets `ForceAuthn="true"` in the SAML request; providers that don\'t support it are unaffected.',
              },
              example: 'login',
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'OK',
      content: { 'application/json': { schema: SsoAuthorizeUrlResponseSchema } },
    },
    302: {
      description: '',
      headers: z.object({
        Location: z
          .url()
          .exactOptional()
          .openapi({ param: { required: false } }),
      }),
    },
  },
  security: [],
})

