export const getSsoProfileRoute = createRoute({
  method: 'get',
  path: '/sso/profile',
  tags: ['sso'],
  summary: 'Get a User Profile',
  description:
    "Exchange an access token for a user's [Profile](/reference/sso/profile). Because this profile is returned in the [Get a Profile and Token endpoint](/reference/sso/profile/get-profile-and-token) your application usually does not need to call this endpoint. It is available for any authentication flows that require an additional endpoint to retrieve a user's profile.",
  operationId: 'SsoController_getProfile',
  responses: {
    200: { description: 'OK', content: { 'application/json': { schema: ProfileSchema } } },
    401: {
      description: 'Unauthorized',
      content: { 'application/json': { schema: UnauthorizedErrorBodySchema } },
    },
    404: { description: 'Not Found', content: { 'application/json': { schema: ErrorBodySchema } } },
  },
  security: [{ access_token: [] }],
})

export const postSsoTokenRoute = createRoute({
  method: 'post',
  path: '/sso/token',
  tags: ['sso'],
  summary: 'Get a Profile and Token',
  description:
    'Get an access token along with the user [Profile](/reference/sso/profile) using the code passed to your [Redirect URI](/reference/sso/get-authorization-url/redirect-uri).',
  operationId: 'SsoController_token',
  request: {
    query: z.object({
      client_id: z
        .string()
        .openapi({
          param: {
            name: 'client_id',
            required: true,
            in: 'query',
            description: 'The client ID of the WorkOS environment.',
            schema: { example: 'client_01HZBC6N1EB1ZY7KG32X', type: 'string' },
          },
          example: 'client_01HZBC6N1EB1ZY7KG32X',
        }),
      client_secret: z
        .string()
        .openapi({
          param: {
            name: 'client_secret',
            required: true,
            in: 'query',
            description: 'The client secret of the WorkOS environment.',
            schema: { example: 'sk_example_123456789', type: 'string' },
          },
          example: 'sk_example_123456789',
        }),
      code: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'code',
            required: false,
            in: 'query',
            description:
              'The authorization code received from the authorization callback. Required when `grant_type` is `authorization_code`.',
            schema: { format: 'password', example: 'authorization_code_value', type: 'string' },
          },
          example: 'authorization_code_value',
        }),
      grant_type: z
        .enum(['authorization_code', 'urn:ietf:params:oauth:grant-type:token-exchange'])
        .openapi({
          param: {
            name: 'grant_type',
            required: true,
            in: 'query',
            description: 'The grant type for the token request.',
            schema: {
              example: 'authorization_code',
              enum: ['authorization_code', 'urn:ietf:params:oauth:grant-type:token-exchange'],
              type: 'string',
            },
          },
          example: 'authorization_code',
        }),
    }),
    body: { content: { 'application/json': { schema: TokenQueryDtoSchema } }, required: true },
  },
  responses: {
    200: { description: 'OK', content: { 'application/json': { schema: SsoTokenResponseSchema } } },
    201: { description: 'Created' },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: OAuthErrorBodySchema } },
    },
    404: { description: 'Not Found', content: { 'application/json': { schema: ErrorBodySchema } } },
    422: {
      description: 'Unprocessable Entity',
      content: { 'application/json': { schema: ErrorBodySchema } },
    },
  },
  security: [],
})

