export const getVaultV1KvRoute = createRoute({
  method: 'get',
  path: '/vault/v1/kv',
  tags: ['vault'],
  summary: 'List objects',
  description: 'List all encrypted objects with cursor-based pagination.',
  operationId: 'JumpWireWeb.DataVaultController.index',
  request: {
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            description: 'Upper limit on the number of objects to return.',
            in: 'query',
            name: 'limit',
            required: false,
            schema: { default: 10, example: 10, minimum: 1, type: 'integer' },
          },
          example: 10,
        }),
      before: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Cursor for the previous page of results.',
            in: 'query',
            name: 'before',
            required: false,
            schema: { example: 'b21f3a8c-7e4d-4b1a-9c5e-2d8f6a7b3c4e', type: 'string' },
          },
          example: 'b21f3a8c-7e4d-4b1a-9c5e-2d8f6a7b3c4e',
        }),
      after: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Cursor for the next page of results.',
            in: 'query',
            name: 'after',
            required: false,
            schema: { example: 'a10e2b7d-6c3f-4a2b-8d1e-3f9a5b8c7d6e', type: 'string' },
          },
          example: 'a10e2b7d-6c3f-4a2b-8d1e-3f9a5b8c7d6e',
        }),
      order: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            description: 'Sort direction for results.',
            in: 'query',
            name: 'order',
            required: false,
            schema: { enum: ['asc', 'desc'], example: 'desc', type: 'string' },
          },
          example: 'desc',
        }),
      search: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter results by name or structured search JSON.',
            in: 'query',
            name: 'search',
            required: false,
            schema: { example: 'my-secret', type: 'string' },
          },
          example: 'my-secret',
        }),
      updatedAfter: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description: 'ISO 8601 timestamp to filter by last modified time.',
            in: 'query',
            name: 'updatedAfter',
            required: false,
            schema: { example: '2024-01-01T00:00:00Z', format: 'date-time', type: 'string' },
          },
          example: '2024-01-01T00:00:00Z',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Object list.',
      content: { 'application/json': { schema: ObjectListResponseSchema } },
    },
    400: { description: 'Bad request.', content: { 'application/json': { schema: ErrorSchema } } },
  },
})

